BEGIN
    IF getdatabaseencoding() <> 'UTF8' THEN
        RAISE EXCEPTION 'PAC-134 migration 045: the database encoding is %, not UTF8; paceday_go_lower needs UTF8', getdatabaseencoding();
    END IF;
    IF cardinality(from_cp) <> 1798 OR cardinality(to_cp) <> 1798 THEN
        RAISE EXCEPTION 'PAC-134 migration 045: % and % code points, expected 1798 each', cardinality(from_cp), cardinality(to_cp);
    END IF;
    SELECT string_agg(chr(u.f), '' ORDER BY u.i), string_agg(chr(u.t), '' ORDER BY u.i)
      INTO from_s, to_s
      FROM unnest(from_cp, to_cp) WITH ORDINALITY AS u(f, t, i);
