CREATE FUNCTION paceday_go_lower(t text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $body$
    SELECT CASE WHEN octet_length(t) = char_length(t)
                THEN lower(t COLLATE "C")
                ELSE translate(t, %L, %L)
           END
$body$$create$, from_s, to_s);
END $pac134$;

COMMENT ON FUNCTION paceday_go_lower(text) IS
    'PAC-134: Go strings.ToLower (unicode 15.0.0, go1.26.0): lower() under C for ASCII text, else one translate(); pinned by the AC-21 test. Never use in an index, CHECK or generated column.';

